-- ============================================================
--  بيانات متابعة الاستراتيجيات المؤسسية — من ملف الإدارة
--  43 جهة. آمن للتكرار: يحذف بذرة العرض القديمة ثم يُدرج،
--  ولا يدهس صفاً عدّلته لاحقاً (on conflict do nothing).
-- ============================================================
delete from public.perf_items
 where section = 'inststrat' and data->>'demo' = 'true';

on conflict (section, id) do nothing;

select count(*) as "صفوف المؤسسية" from public.perf_items where section='inststrat';
